Description
Percentage of cases with a sub-process cycle time under the selected SLA
Unit None
Format .0%
Desired direction NONE
Process type None
Business concept Labor Productivity (From: Universal), Customer Satisfaction (From: Universal), Working Capital Optimization (From: Universal), Compliance (From: Universal), Revenue Growth & Protection (From: Universal)

AVG ( CASE WHEN ${UNIVERSAL_Variable_INPUT__TIMESCALE_RUNTIME}_BETWEEN ( PU_${UNIVERSAL_Variable_INPUT__FROMOCCURRENCESUBPROCESS_RUNTIME} ( CASE_TABLE ( ${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME} ) , TIMESTAMP_COLUMN ( ${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME} ) , ACTIVITY_COLUMN ( ${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME} ) = '${UNIVERSAL_Variable_INPUT__FROMACTIVITYSUBPROCESS_RUNTIME}' ) , PU_${UNIVERSAL_Variable_INPUT__TOOCCURRENCESUBPROCESS_RUNTIME} ( CASE_TABLE ( ${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME} ) , TIMESTAMP_COLUMN ( ${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME} ) , ACTIVITY_COLUMN ( ${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME} ) = '${UNIVERSAL_Variable_INPUT__TOACTIVITYSUBPROCESS_RUNTIME}' ) ) IS NULL THEN NULL WHEN REMAP_TIMESTAMPS ( PU_${UNIVERSAL_Variable_INPUT__TOOCCURRENCESUBPROCESS_RUNTIME}( CASE_TABLE(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), TIMESTAMP_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), ACTIVITY_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}) = '${UNIVERSAL_Variable_INPUT__TOACTIVITYSUBPROCESS_RUNTIME}' ) , MINUTES,       WEEKDAY_CALENDAR (${UNIVERSAL_Variable_INPUT__CALENDARWEEK_RUNTIME})) / (CASE WHEN '${UNIVERSAL_Variable_INPUT__TIMESCALE_RUNTIME}' = 'DAYS' THEN 1440 WHEN '${UNIVERSAL_Variable_INPUT__TIMESCALE_RUNTIME}' = 'HOURS' THEN 60 ELSE 1 END )
-
REMAP_TIMESTAMPS ( PU_${UNIVERSAL_Variable_INPUT__FROMOCCURRENCESUBPROCESS_RUNTIME}( CASE_TABLE(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), TIMESTAMP_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), ACTIVITY_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}) = '${UNIVERSAL_Variable_INPUT__FROMACTIVITYSUBPROCESS_RUNTIME}' ) ,MINUTES,       WEEKDAY_CALENDAR (${UNIVERSAL_Variable_INPUT__CALENDARWEEK_RUNTIME})) / (CASE WHEN '${UNIVERSAL_Variable_INPUT__TIMESCALE_RUNTIME}' = 'DAYS' THEN 1440 WHEN '${UNIVERSAL_Variable_INPUT__TIMESCALE_RUNTIME}' = 'HOURS' THEN 60 ELSE 1 END ) <= ${UNIVERSAL_Variable_INPUT__SLASUBPROCESS_RUNTIME} THEN 1.0 ELSE 0.0 END )
